# Dated override chains and paired descriptive assessment.
override_monitoring<-function(pre_override,post_override,override_ledger,policy,design,metrics,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);p<-.ex_object(policy,'policy');authorities<-.ex_ids(p$approved_authorities,'approved_authorities');.vb_string(p$reference,'policy reference');threshold<-.vb_number(p$concentration_threshold,'concentration_threshold');if(threshold<=0||threshold>1).cr_error('OVERRIDE_POLICY','Concentration threshold must be in (0,1]')
 pre<-.ex_object(pre_override,'pre_override');post<-.ex_object(post_override,'post_override');a<-.mm_cohort(pre$cohort);b<-.mm_cohort(post$cohort);models<-lapply(list(a,b),function(x)sort(unique(vapply(x$rows,function(r)r$model_id,character(1)))));if(any(lengths(models)!=1)||identical(models[[1]],models[[2]])).cr_error('OVERRIDE_MODELS','Distinct pre/post model identifiers required');pre_id<-models[[1]][1];post_id<-models[[2]][1];entries<-setNames(list(pre,post),c(pre_id,post_id));compared<-benchmark_predictions(entries,reference_model_id=pre_id,metrics=metrics,matching_policy='strict',multiple_comparisons='none',design=d,uncertainty=uncertainty,cluster_resamples=cluster_resamples,confidence_level=confidence_level,context=context)$value
 left<-setNames(a$rows,vapply(a$rows,function(r)r$case_id,character(1)));right<-setNames(b$rows,vapply(b$rows,function(r)r$case_id,character(1)));if(!is.list(override_ledger)||any(!vapply(override_ledger,is.list,logical(1)))).cr_error('OVERRIDE_LEDGER','Override ledger must be an array of objects');ledger<-override_ledger;.ex_ids(lapply(ledger,function(r)r$override_id),'override IDs',empty=TRUE);index<-list();audit<-list();reasons<-list();author_counts<-list();expired<-future<-character()
 increment<-function(x,key){x[[key]]<-if(is.null(x[[key]]))1 else x[[key]]+1;x}
 for(entry in ledger){for(key in c('case_id','reason','authority')).vb_string(entry[[key]],key);if(is.null(left[[entry$case_id]])).cr_error('OVERRIDE_CASE','Ledger references an unknown paired case');applied<-.cr_data_date(entry$applied_at,'applied_at');known<-.cr_data_date(entry$known_at,'known_at');expiry<-.cr_data_date(entry$expires_at,'expires_at');if(known<applied||expiry<=applied).cr_error('OVERRIDE_DATE','Knowledge must not precede action; expiry must follow action');for(key in c('from_pd','to_pd')){v<-.vb_number(entry[[key]],key);if(v<0||v>1).cr_error('OVERRIDE_PD','Override probabilities must be in [0,1]')};date<-.cr_data_date(left[[entry$case_id]]$forecast_at,'forecast_at');status<-'ACTIVE';if(known>date||applied>date){status<-'NOT_YET_KNOWN';future<-c(future,entry$override_id)}else if(expiry<=date){status<-'EXPIRED';expired<-c(expired,entry$override_id)}else if(!entry$authority%in%authorities).cr_error('OVERRIDE_AUTHORITY','Active override lacks approved authority');if(status=='ACTIVE'){index[[entry$case_id]]<-c(index[[entry$case_id]],list(entry));reasons<-increment(reasons,entry$reason);author_counts<-increment(author_counts,entry$authority)};audit[[length(audit)+1]]<-list(override_id=entry$override_id,case_id=entry$case_id,status=status)}
 traces<-list();changed<-up<-down<-0;multiple<-character();by_group<-list()
 for(case_id in sort(names(left))){row<-left[[case_id]];entries<-index[[case_id]];if(is.null(entries))entries<-list();if(length(entries)){keys<-vapply(entries,function(e)paste(e$applied_at,e$known_at,e$override_id),character(1));entries<-entries[order(keys)];datekeys<-vapply(entries,function(e)paste(e$applied_at,e$known_at),character(1));if(anyDuplicated(datekeys)).cr_error('OVERRIDE_AMBIGUITY','Equally dated active actions need upstream resolution')};current<-row$pd;for(entry in entries){if(abs(entry$from_pd-current)>1e-12).cr_error('OVERRIDE_CHAIN','Active override chain does not start at pre-override PD or has a gap');current<-entry$to_pd};if(abs(current-right[[case_id]]$pd)>1e-12).cr_error('OVERRIDE_REPLAY','Post-override PD does not reproduce the active ledger chain');delta<-right[[case_id]]$pd-row$pd;applied<-length(entries)>0;changed<-changed+applied;up<-up+(delta>0);down<-down+(delta<0);if(length(entries)>1)multiple<-c(multiple,case_id);traces[[length(traces)+1]]<-list(case_id=case_id,pre_pd=row$pd,post_pd=right[[case_id]]$pd,pd_change=delta,active_override_ids=lapply(entries,function(e)e$override_id),active_count=length(entries),direction=if(delta>0)'PD_INCREASE'else if(delta<0)'PD_DECREASE'else'UNCHANGED');for(type in c('segment','cohort')){key<-paste0(type,':',row[[type]]);group<-by_group[[key]];if(is.null(group))group<-list(cases=0,overridden_cases=0);group$cases<-group$cases+1;group$overridden_cases<-group$overridden_cases+applied;by_group[[key]]<-group}}
 by_group<-lapply(by_group,function(g){g$override_rate<-g$overridden_cases/g$cases;g});N<-length(left);total_actions<-sum(unlist(reasons));concentration<-list();for(label in c('reason','authority')){counts<-if(label=='reason')reasons else author_counts;if(!length(counts))counts<-structure(list(),names=character());counts<-counts[sort(names(counts))];share<-if(total_actions>0)max(unlist(counts))/total_actions else NULL;concentration[[label]]<-list(counts=counts,maximum_share=share,flag=isTRUE(total_actions>0&&share>threshold),threshold=threshold,denominator='ACTIVE_ACTIONS')};if(!length(by_group))by_group<-structure(list(),names=character());values<-list(cases=N,overridden_cases=changed,override_rate=if(N)changed/N else NULL,pd_increase_cases=up,pd_decrease_cases=down,unchanged_cases=N-up-down,by_group=by_group,concentration=concentration,paired_performance=compared$metrics);rows<-lapply(a$rows,function(r)list(prediction_id=r$forecast_id,entity_id=r$entity_id,cluster_id=r$cluster_id));diagnostics<-list(policy=p,ledger_fingerprint=.cr_hash(ledger),ledger_audit=audit,case_traces=traces,expired_override_ids=as.list(sort(expired)),not_yet_known_override_ids=as.list(sort(future)),multiple_active_case_ids=as.list(multiple),performance_coverage=compared$coverage,performance_diagnostics=compared$diagnostics,causal_effect_identified=FALSE,rate_population='ALL_PAIRED_FORECAST_CASES',performance_population='COMMON_MATURE_ELIGIBLE_CASES',active_interval='applied_at <= forecast_at < expires_at; known_at <= forecast_at');.vb_result('override_monitoring',values,d,rows,list(),compared$uncertainty,context,diagnostics)
}

support_transfer_backtest<-function(records,stage_contract,union_contract,design,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);rows<-.vb_records(records,d);stages<-.ex_object(stage_contract,'stage_contract');union<-.ex_object(union_contract,'union_contract');stagenames<-sort(names(stages));if(!length(stagenames)).cr_error('STAGE_CONTRACT','At least one identified stage required')
 for(name in stagenames){spec<-.ex_object(stages[[name]],'stage specification');.vb_string(name,'stage name');.vb_string(spec$event_definition,'event_definition');.vb_string(spec$reference,'reference');if(!(spec$kind%in%c('binary','amount'))||!is.logical(spec$observable)||length(spec$observable)!=1||is.na(spec$observable)).cr_error('STAGE_CONTRACT','Declare binary/amount kind and genuinely observable stage');if(spec$kind=='amount'){.vb_string(spec$currency,'currency');if(!identical(spec$currency,d$currency)).cr_error('STAGE_CURRENCY','Amount stage currency must equal validation currency')}}
 for(key in c('component_a','component_b','joint','union')){s<-union[[key]];if(is.null(s)||!s%in%stagenames||stages[[s]]$kind!='binary').cr_error('STAGE_UNION','Four binary stage names required')};if(length(unique(unlist(union)))!=4).cr_error('STAGE_UNION','Distinct stage names required');n<-length(rows);pred<-observed<-setNames(lapply(stagenames,function(s)rep(0,n)),stagenames);weight<-rep(1,n);eligible<-setNames(lapply(stagenames,function(s)rep(FALSE,n)),stagenames);excluded<-setNames(lapply(stagenames,function(s)list()),stagenames);reconciliation<-list()
 for(i in seq_along(rows)){row<-rows[[i]];predictions<-.ex_object(row$stage_predictions,'stage_predictions');outcomes<-.ex_object(row$stage_outcomes,'stage_outcomes');if(!setequal(names(predictions),stagenames)||!all(names(outcomes)%in%stagenames)).cr_error('STAGE_SCHEMA','Complete prediction stage keys and known outcome keys required');weight[i]<-.vb_number(if(is.null(row$weight))1 else row$weight,'weight',0);event_dates<-list()
 for(name in stagenames){spec<-stages[[name]];p<-.vb_number(predictions[[name]],'stage prediction',0);if(spec$kind=='binary'&&p>1).cr_error('STAGE_PD','Binary probability exceeds one');pred[[name]][i]<-p;outcome<-outcomes[[name]];reason<-NULL
 if(!spec$observable){if(!is.null(outcome)).cr_error('STAGE_COUNTERFACTUAL','Unobservable stages cannot carry purported outcomes');reason<-'STAGE_NOT_OBSERVABLE'}else if(.cr_data_date(row$horizon_end,'horizon_end')>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff'))reason<-'IMMATURE_HORIZON'else if(is.null(outcome))reason<-'STAGE_OUTCOME_MISSING'else{outcome<-.ex_object(outcome,'stage outcome');known<-.cr_data_date(outcome$known_at,'stage known_at');end<-.cr_data_date(row$horizon_end,'horizon_end');complete<-.cr_data_date(outcome$complete_through,'complete_through');y<-.vb_number(outcome$value,'stage outcome',0);if(spec$kind=='binary'&&!(y%in%c(0,1))).cr_error('STAGE_OUTCOME','Binary stage must be zero or one');if(known<.cr_data_date(row$as_of,'as_of')||complete>known).cr_error('STAGE_LOOKAHEAD','Stage coverage cannot exceed knowledge date');ids<-.ex_ids(outcome$event_ids,'event_ids',empty=TRUE);if(spec$kind=='binary'&&((y==1&&!length(ids))||(y==0&&length(ids)))).cr_error('STAGE_EVENT','Positive stages need source IDs; negative stages have none');if(spec$kind=='binary'){times<-outcome$event_times;if(is.null(times)||length(times)!=length(ids)).cr_error('STAGE_EVENT','Each source event requires aligned date');for(j in seq_along(times)){time<-times[[j]];event_id<-ids[j];if(!is.null(event_dates[[event_id]])&&!identical(event_dates[[event_id]],time)).cr_error('STAGE_EVENT','Shared source event has inconsistent dates');event_dates[[event_id]]<-time;t<-.cr_data_date(time,'stage event date');if(t<.cr_data_date(row$as_of,'as_of')||t>end||t>known).cr_error('STAGE_EVENT','Event outside forecast horizon or knowledge date')}};if(known>.cr_data_date(d$evaluation_cutoff,'evaluation_cutoff'))reason<-'STAGE_OUTCOME_NOT_YET_KNOWN'else if(complete<end)reason<-'INCOMPLETE_STAGE_FOLLOWUP'else if(weight[i]==0)reason<-'ZERO_EVALUATION_WEIGHT'else{observed[[name]][i]<-y;eligible[[name]][i]<-TRUE}}
 if(!is.null(reason))excluded[[name]][[length(excluded[[name]])+1]]<-list(prediction_id=row$prediction_id,reason=reason)
 }
 keys<-unlist(union[c('component_a','component_b','joint','union')],use.names=FALSE);p<-vapply(keys,function(s)pred[[s]][i],numeric(1));if(p[3]<max(0,p[1]+p[2]-1)-1e-12||p[3]>min(p[1],p[2])+1e-12||abs(p[4]-(p[1]+p[2]-p[3]))>1e-12).cr_error('STAGE_UNION','Predictions violate Frechet or double-count joint');all_observed<-all(vapply(keys,function(s)eligible[[s]][i],logical(1)));ids<-NULL;if(all_observed){y<-vapply(keys,function(s)observed[[s]][i],numeric(1));if(y[3]!=y[1]*y[2]||y[4]!=max(y[1],y[2])).cr_error('STAGE_RECONCILIATION','Observed joint/union disagree with component events');ids<-sort(unique(c(unlist(outcomes[[keys[1]]]$event_ids),unlist(outcomes[[keys[2]]]$event_ids))));if(!setequal(unlist(outcomes[[keys[4]]]$event_ids),ids)).cr_error('STAGE_RECONCILIATION','Union provenance must deduplicate component IDs')};reconciliation[[length(reconciliation)+1]]<-list(prediction_id=row$prediction_id,predicted_union=p[4],predicted_joint=p[3],observed_reconciled=all_observed,distinct_component_event_ids=if(is.null(ids)&&!all_observed)NULL else as.list(ids),distinct_component_event_count=if(all_observed)length(ids)else NULL)
 }
 calculate<-function(draw){out<-list();for(name in stagenames){w<-weight*draw*eligible[[name]];m<-.vb_errors(pred[[name]],observed[[name]],w);m$event_definition<-stages[[name]]$event_definition;m$kind<-stages[[name]]$kind;m$observable<-stages[[name]]$observable;if(stages[[name]]$kind=='binary')m['brier']<-list(if(any(w>0))sum(w*(pred[[name]]-observed[[name]])^2)/sum(w)else NULL);out[[name]]<-m};out};values<-calculate(rep(1,n));draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);samples<-if(is.null(draws))NULL else lapply(draws,function(draw){result<-calculate(draw);sample<-list();for(name in stagenames)for(key in c('bias','mae','rmse',if(stages[[name]]$kind=='binary')'brier'))sample[paste0(name,'/',key)]<-list(result[[name]][[key]]);sample});all_excluded<-list();for(i in seq_along(rows))if(!any(vapply(stagenames,function(s)eligible[[s]][i],logical(1))))all_excluded[[length(all_excluded)+1]]<-list(prediction_id=rows[[i]]$prediction_id,reason='NO_OBSERVABLE_MATURE_STAGE');diagnostics<-list(stage_contract=stages,union_contract=union,stage_exclusions=excluded,event_reconciliation=reconciliation,stage_labels_inferred_from_final_label=FALSE,support_counterfactual_identified=FALSE,amounts_are_observed_contractual_realizations=TRUE,uncertainty_population='DECLARED_SAMPLING_CLUSTERS_CONDITIONAL_ON_STAGE_OBSERVABILITY');.vb_result('support_transfer_backtest',list(by_stage=values),d,rows,all_excluded,.vb_bands(samples,confidence_level),context,diagnostics)
}
